let chosenCrop='',viewName='all',detailTab='basic',detailEntity=null,recommendType='Intervention';
const oldContext=contextMatches;
contextMatches=e=>(!chosenCrop||data.nodes.some(n=>['Crop','Variety'].includes(n.type)&&n.name===chosenCrop))&&oldContext(e);
const oldFilter=filter;
filter=function(){oldFilter();dashboardFiltered();};
for(const id of ['search','kind','scope','region','crop','stage','entity-type','as-of']){const event=id==='search'?'input':'change';$(id).removeEventListener(event,oldFilter);$(id).addEventListener(event,()=>{if(id==='crop')chosenCrop=$(id).value;filter();});}
const oldRender=render;
render=function(){oldRender();for(const g of $('nodes').children){const n=nodeById(g.dataset.id),text=g.querySelector('text');if(n.name.length>9)text.textContent=n.name.slice(0,8)+'…';const icon=svgEl('text',{y:5,'text-anchor':'middle',style:'font-size:14px;stroke:none;fill:white;pointer-events:none'});icon.textContent=({Crop:'🍐',Stage:'♧',Condition:'≋',Disease:'✿',Pest:'✣',Intervention:'✧',Risk:'◉',Symptom:'◇'})[n.type]||'·';g.append(icon);if(n.name===chosenCrop){g.querySelector('circle').setAttribute('r',34);text.setAttribute('y',50);}}drawMinimap();recommend();};
const oldLayout=layout;
layout=function(){
 if(visible.nodes.length<10){oldLayout();return;}
 const groups=new Map(),placement={Variety:[450,200],GrowthStage:[510,110],EnvironmentFactor:[280,240],StorageCondition:[200,350],Requirement:[220,440],AgriculturalPractice:[300,510],HarvestProcess:[400,540],PreventionMeasure:[350,440],QualityIndicator:[740,530],PostharvestRisk:[640,580],Crop:[500,210],Region:[500,450],Stage:[510,110],Condition:[280,240],Intervention:[300,510],Disease:[750,160],Pest:[860,300],Symptom:[830,470],Risk:[640,580],State:[520,570],PhysiologicalDisorder:[650,420],Metric:[160,430]};
 for(const n of visible.nodes){if(!groups.has(n.type))groups.set(n.type,[]);groups.get(n.type).push(n);}
 positions=new Map();
 for(const [type,nodes]of groups){const [cx,cy]=placement[type]||[500,350];nodes.forEach((n,i)=>{const ring=Math.floor(i/7),angle=(i%7)*Math.PI*2/7-Math.PI/2,r=nodes.length===1?0:65+ring*50;positions.set(n.id,{x:cx+Math.cos(angle)*r,y:cy+Math.sin(angle)*r});});}
 const root=visible.nodes.find(n=>n.name===chosenCrop);if(root)positions.set(root.id,{x:500,y:350});
};
const oldNode=showNode;
showNode=function(n){oldNode(n);detailEntity=n;detailTab='basic';renderDetails();};
const oldEdge=showEdge;
showEdge=function(e){detailEntity=null;oldEdge(e);$('entity-heading').replaceChildren(el('span','◉','entity-icon'),el('h2','关系证据'));document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab==='evidence'));};
function sourceLink(parent,s){const a=el('a',s.title);try{const u=new URL(s.url);if(['http:','https:'].includes(u.protocol)){a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';}}catch{}parent.append(a,el('p',`${s.evidence_level||'未分级'} · ${s.region||'未标定地区'} · ${s.review_method||'待复核'}`));}
function renderDetails(){
 const p=$('detail-content');p.replaceChildren();
 document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===detailTab));
 if(!detailEntity){$('entity-heading').replaceChildren(el('p','请选择实体'));p.append(el('p','请先选择图中实体。'));return;}
 const n=detailEntity,edges=matching.edges.filter(e=>contextIds(e).includes(n.id));
 $('entity-heading').replaceChildren(el('span',n.type==='Crop'?'🍐':n.type==='Disease'?'◉':'◇','entity-icon'));
 const head=el('div');head.append(el('h2',n.name));badge(head,types[n.type]||n.type);$('entity-heading').append(head);
 const row=(name,value)=>{const r=el('div',undefined,'info-row');r.append(el('span',name),el('span',value));p.append(r);};
 if(detailTab==='basic'){
  if(n.name==='梨')p.append(el('p','这是资料中的梨类通用实体；中心的“泊头鸭梨”是浏览导航。通用资料不等于已经在泊头鸭梨上验证。','scope-note'));
  const photo=graphImage(n.name);
  if(photo){const img=el('img',undefined,'disease-detail-photo');img.src=photo.src;img.alt=photo.subject||n.name; p.append(img,imageCredit(photo));}
  else if(['Disease','PhysiologicalDisorder'].includes(n.type))p.append(el('p','该病害图片待补充，暂不使用其他病害照片代替。','image-missing'));
  const gallery=window.GRAPH_IMAGE_GALLERIES?.[['黑星病','梨黑星病'].includes(n.name)?'黑星病':n.name];
  if(gallery?.length){p.append(el('h3','症状参考图片'),el('p','用户提供的示意图，不替代现场诊断。'));const strip=el('div',undefined,'reference-photo-grid');for(const photo of gallery)strip.append(referenceFigure(photo,photo.caption));p.append(strip);}
  row('中文名',n.name);row('实体类型',types[n.type]||n.type);row('适用作物',[...new Set(edges.map(e=>label(e.crop)))].join('、')||'待补充');row('适用地区',[...new Set(edges.map(e=>e.region))].join('、')||'待补充');row('关联知识',`${edges.length} 条`);row('审核状态',[...new Set(edges.map(e=>reviews[e.review_status]||e.review_status))].join('、')||'仅本体实体');
  p.append(el('p','具体症状、措施及条件请查看关联关系。没有原文依据的危害部位、严重程度等字段不自动补写。'));
 }else if(detailTab==='relations'){
  edges.forEach(e=>{const b=el('button',`${label(e.source)} → ${relations[e.relation]||e.relation} → ${label(e.target)}`,'relation-card');b.onclick=()=>showEdge(e);p.append(b);});if(!edges.length)p.append(el('p','当前条件下暂无关联知识。'));
 }else if(detailTab==='time'){
  row('适用阶段',[...new Set(edges.flatMap(e=>e.stage_ids.map(label)))].join('、')||'原文未标定');row('适用地区',[...new Set(edges.map(e=>e.region))].join('、')||'原文未标定');row('已知生效日',[...new Set(edges.map(e=>e.valid_from).filter(Boolean))].join('、')||'未知');p.append(el('p','地区适用范围不等于观测地点；当前没有地块坐标或真实病害时序监测数据。'));
 }else{
  const ids=new Set(edges.flatMap(e=>e.evidence_ids));data.sources.filter(s=>ids.has(s.id)).forEach(s=>{const card=el('div',undefined,'source');sourceLink(card,s);p.append(card);});if(!ids.size)p.append(el('p','当前条件下没有关联证据。'));
 }
}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{detailTab=b.dataset.tab;renderDetails();});
function drawMinimap(){const map=$('minimap');map.replaceChildren();for(const n of visible.nodes){const p=positions.get(n.id);if(p)map.append(svgEl('circle',{cx:p.x,cy:p.y,r:14,fill:color(n.type)}));}}
const oldPositions=updatePositions;
updatePositions=function(){oldPositions();drawMinimap();};
$('minimap-button').onclick=()=>$('reset').click();
function dashboardFiltered(){
 $('path-preview').replaceChildren(el('p','选择起点与终点，查询当前条件下的有向证据路径。'));
 $('graph-title').textContent=(chosenCrop||'全部作物')+'知识图谱';
 $('updated-date').textContent=data.sources.map(s=>s.reviewed_at).filter(Boolean).sort().at(-1)||'暂无记录';
 document.querySelectorAll('[data-crop]').forEach(b=>b.classList.toggle('active',b.dataset.crop===chosenCrop));
 if(chosenCrop&&!data.nodes.some(n=>['Crop','Variety'].includes(n.type)&&n.name===chosenCrop)){
  $('empty').hidden=false;$('empty').replaceChildren(el('h3',chosenCrop+'尚无已审核知识'),el('p','已切换作物；当前不能用鸭梨资料替代该作物。'));matching={nodes:[],edges:[]};visible={nodes:[],edges:[]};render();
 }
 if(viewName==='all'&&!$('search').value&&!$('entity-type').value&&matching.nodes.length>60){
  const groups=new Map();for(const e of matching.edges){const type=nodeById(e.source)?.type||'other';if(!groups.has(type))groups.set(type,[]);groups.get(type).push(e);}
  const ids=new Set(),edges=[];let offset=0;
  while(offset<4){for(const bucket of groups.values()){const e=bucket[offset];if(e&&new Set([...ids,e.source,e.target]).size<=40){ids.add(e.source);ids.add(e.target);edges.push(e);}}offset++;}
  const root=data.nodes.find(n=>n.name===(chosenCrop||'泊头鸭梨'));if(root&&matching.nodes.some(n=>n.id===root.id))ids.add(root.id);
  visible={nodes:data.nodes.filter(n=>ids.has(n.id)),edges,total:matching.nodes.length};layout();render();
 }
 recommend();
 if(detailEntity&&!matching.nodes.some(n=>n.id===detailEntity.id)){detailEntity=null;renderDetails();}
 else if(detailEntity)renderDetails();
}
const oldFill=fillFilters;
fillFilters=function(){oldFill();for(const name of ['黄骅旱碱麦','沧州金丝小枣','设施蔬菜'])if(!Array.from($('crop').options).some(o=>o.value===name))$('crop').add(new Option(name+'（待收录）',name));};
function navigate(topic){
 const crop=chosenCrop;resetFilters();chosenCrop=crop;$('crop').value=crop;viewName=topic;
 document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===topic));
 if(topic==='production')$('entity-type').value='GrowthStage';
 if(topic==='disease')$('search').value='害';
 if(topic==='environment')$('entity-type').value='EnvironmentFactor';
 if(topic==='harvest')$('stage').value='采收期';
 if(topic==='storage')$('stage').value='储藏期';
 if(topic==='risk')$('entity-type').value='PostharvestRisk';
 if(topic==='intervention')$('entity-type').value='PreventionMeasure';
 if(topic==='spacetime'){$('entity-type').value='GrowthStage';openTool('spacetime');}
 filter();
}
document.querySelectorAll('[data-crop]').forEach(b=>b.onclick=()=>{chosenCrop=b.dataset.crop;navigate('all');});
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));
$('clear-filters').onclick=()=>{chosenCrop='';navigate('all');};
const legend=[['Crop','作物/品种'],['GrowthStage','生育阶段'],['EnvironmentFactor','环境因素'],['Disease','病害'],['Pest','虫害'],['Symptom','症状'],['PreventionMeasure','防控措施'],['PostharvestRisk','采后风险'],['Region','地区'],['PhysiologicalDisorder','生理障碍']];
for(const [type,title]of legend){const b=el('button');const dot=el('i');dot.style.background=color(type);b.append(dot,el('span',title));b.onclick=()=>{$('entity-type').value=type;filter();};$('legend').append(b);}
function openDialog(id){if(!$(id).open)$(id).showModal();}
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('advanced-open').onclick=()=>openDialog('advanced-dialog');$('advanced-apply').onclick=()=>{chosenCrop=$('crop').value;filter();$('advanced-dialog').close();};$('advanced-reset').onclick=()=>{chosenCrop='';resetFilters();};
$('directory-open').onclick=()=>openDialog('directory-dialog');$('node-list').addEventListener('click',e=>{if(e.target.closest('button'))$('directory-dialog').close();});
$('search-form').onsubmit=e=>{e.preventDefault();chosenCrop=$('crop').value;filter();};
function recommend(){
 const p=$('recommendations');p.replaceChildren();
 const edges=matching.edges.filter(e=>recommendType==='storage'?e.stage_ids.some(id=>label(id)==='储藏期'):[e.source,e.target].some(id=>(recommendType==='Intervention'?['Intervention','PreventionMeasure']: [recommendType]).includes(nodeById(id)?.type))).slice(0,4);
 edges.forEach((e,i)=>{const r=el('div',undefined,'recommend-row');r.append(el('small',String(i+1)),el('span',e.claim));const b=el('button','查看');b.onclick=()=>showEdge(e);r.append(b);p.append(r);});
 if(!edges.length)p.append(el('p','当前筛选下暂无该类已收录知识。'));
}
